function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function busy(text,fn){$('#loading-text').textContent=text;$('#loading').hidden=false;try{await new Promise(r=>setTimeout(r,30));return await fn()}catch(e){showError(e.message);return null}finally{$('#loading').hidden=true}}
function showError(text){$('#modal-content').innerHTML='<h2>Vorgang konnte nicht abgeschlossen werden</h2><p>'+esc(text)+'</p><button data-action="close-modal">Schließen</button>';if(!$('#modal').open)$('#modal').showModal()}
async function commit(next){await KPStorage.write(next);state=next;if(KPStorage.deletionWarning){$('#cloud-notice').textContent=KPStorage.deletionWarning;$('#cloud-notice').hidden=false;}}

function activePrice(){return state.priceVersions.find(x=>x.id===state.activePrice)}function activeParameters(){return state.parameterVersions.find(x=>x.id===state.activeParameters)}
function projectReadOnly(p=project){return !!(p&&(p.protected||p.status==='Abgeschlossen'))}
function setProjectBasis(p,ap,pr){if(!p||p.status!=='Entwurf'||p.protected)return p;p.pricingModel=13;if(ap){p.parameters=clone(ap.overrides);p.parameterVersion=ap.id;}if(pr){p.priceVersion=pr.id;p.priceName=pr.name;p.priceOverrides=clone(pr.overrides);p.pdsCatalog=clone(pr.pdsCatalog||null);}return p}
function syncDraftBasis(p){return setProjectBasis(p,activeParameters(),activePrice())}
function refreshDraftSnapshots(next){return next} // Drafts adopt the current basis when opened/saved; no bulk project overwrite.

function pct(v){const n=Number(v||0);return new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n)+' %'}
async function newProject(template=null){let next=clone(state);next.lastNumber=await KPStorage.reserveNumber();const p={id:id(),number:'TGA-'+new Date().getFullYear()+'-'+String(next.lastNumber).padStart(4,'0'),customer:'',title:'',creator:USER,created:now(),modified:now(),status:'Entwurf',pricingModel:13,parameters:clone(activeParameters().overrides),parameterVersion:activeParameters().id,priceVersion:activePrice().id,priceName:activePrice().name,priceOverrides:clone(activePrice().overrides),pdsCatalog:clone(activePrice().pdsCatalog||null),inputs:{[P]:{G4:next.lastNumber,M15:null}},history:[],optimizer:{values:{E3:null,E4:null,E5:null,E6:null,E8:null,E10:null,E12:null,E14:null,E16:'TGA'},slots:[null,null,null,null]},catalogServices:[],supplements:[],locked:false,deviationThreshold:20};
 if(template){p.inputs=D.merge(p.inputs,template.inputs);p.parameters=D.merge(p.parameters,{[B]:template.inputs[B]});delete p.inputs[B];p.inputs[P].G4=next.lastNumber;p.parameterVersion='excel-slot-'+template.number;}
 state.lastNumber=next.lastNumber;project=p;dirty=true;step=0;view='wizard';render();}
function heading(title,text,buttons=''){return '<div class="page-heading"><div><span class="eyebrow">TGA SYSTEMTECHNIK · KALKPRO</span><h1>'+esc(title)+'</h1><p>'+esc(text)+'</p></div><div class="actions">'+buttons+'</div></div>'}
function btn(action,text,cls='',extra=''){if(!isAdmin()&&['delete-project','confirm-delete-project','matrix-save','matrix-generate','matrix-update','matrix-assumptions','matrix-delete','matrix-confirm-delete','csv-select','csv-confirm','save-parameters','backup-export','backup-select','backup-confirm','load-archive','confirm-archive'].includes(action))return '';if(!isAdmin()&&action==='navigate'&&/data-view="(?:upload|parameters)"/.test(extra))return '';return '<button class="'+cls+'" data-action="'+action+'" '+extra+'>'+text+'</button>'}
function noProject(){return heading('Ein Projekt auswählen','Öffne eine gespeicherte Vorkalkulation, um darauf aufzubauen.')+projectTable(state.projects);}
function getInput(sheet,cell){let eng=D.createEngine(project);return eng.safe(sheet,cell)}
function input(sheet,cell,label,type='number',hint='',forceDisabled=false){let val=getInput(sheet,cell);if(val==null||typeof val==='string'&&val.startsWith('#'))val='';const disabled=(projectReadOnly()||forceDisabled)?'disabled':'';return '<label>'+esc(label)+'<input data-sheet="'+esc(sheet)+'" data-cell="'+cell+'" type="'+type+'" '+(type==='number'?'step="any" min="0"':'')+' value="'+esc(val)+'" '+disabled+'>'+ (hint?'<small>'+esc(hint)+'</small>':'')+'</label>'}
function checkbox(sheet,cell,label,hint=''){return '<label class="check"><input type="checkbox" data-sheet="'+esc(sheet)+'" data-cell="'+cell+'" '+(getInput(sheet,cell)===true?'checked':'')+' '+(projectReadOnly()?'disabled':'')+'><span>'+esc(label)+(hint?'<small>'+esc(hint)+'</small>':'')+'</span></label>'}
function selectRoof(row){const labels=['Stockschrauben','Schrägdach','Trapezblech','Flachdach Ost/West','Flachdach Süd'],cols=['D','E','F','G','H'];return '<label>Dach-/Montageart<select data-roof="'+row+'" '+(projectReadOnly()?'disabled':'')+'><option value="">Bitte auswählen</option>'+cols.map((c,i)=>'<option value="'+c+'" '+(getInput(P,c+row)?'selected':'')+'>'+labels[i]+'</option>').join('')+'</select></label>'}
function picks(row,labelRow,start='C',end='P',countRow=null,single=false){let cols=KPEngine.range(start+'1',end+'1').map(x=>x.replace('1',''));return '<div class="selection-grid">'+cols.map(c=>{let label=KP_SOURCE.sheets[P][c+labelRow]?.v;if(!label||String(label).startsWith('='))return '';let out=checkbox(P,c+row,label);if(countRow)out+='<div style="padding:6px 12px">'+input(P,c+countRow,'Menge / '+label,'number')+'</div>';return '<div>'+out+'</div>'}).join('')+'</div>'}
function render(){if(!logged)return;$('#navigation').innerHTML=navigation.filter(x=>isAdmin()||!['upload','parameters'].includes(x[0])).map(([key,icon,label])=>btn('navigate','<span class="nav-icon">'+icon+'</span><span class="nav-text">'+label+'</span>',(view===key||key==='new'&&view==='wizard')?'active':'','data-view="'+key+'"')).join('');$('#header-title').textContent=view==='wizard'?'Vorkalkulation':navigation.find(x=>x[0]===view)?.[2]||'Arbeitsbereich';const pages={dashboard:dashboard,projects:projectsPage,wizard:wizard,actual:actualPage,prices:pricesPage,upload:uploadPage,parameters:parametersPage,matrix:matrixPage,help:helpPage};$('#main').innerHTML=(pages[view]||dashboard)();}
function dashboard(){let saved=state.projects,open=saved.filter(p=>p.status!=='Abgeschlossen'),awaiting=saved.filter(p=>p.locked&&p.actual?.status!=='Abgeschlossen'),closed=saved.filter(p=>p.actual?.status==='Abgeschlossen');let recent=[...saved].sort((a,b)=>b.modified.localeCompare(a.modified)).slice(0,5);
 return heading('Willkommen bei KalkPro.','Von der ersten Kalkulation bis zum tatsächlichen Projektergebnis.',btn('new-project','+ Neue Kalkulation','primary'))+'<div class="grid">'+[['Gespeicherte Projekte',saved.length,'Alle Vor- und Nachkalkulationen'],['Offene Kalkulationen',open.length,'Entwürfe und laufende Projekte'],['Nachkalkulation ausstehend',awaiting.length,'Gesicherte Vorkalkulationen'],['Nachkalkulation abgeschlossen',closed.length,'Vollständig geprüfte Ist-Werte']].map(([l,v,s],i)=>'<div class="card metric '+(i===0?'accent':'')+'"><div class="metric-label">'+l+'</div><strong>'+v+'</strong><small>'+s+'</small></div>').join('')+'</div><div class="card"><div class="subheading"><h2>Zuletzt bearbeitete Projekte</h2>'+btn('navigate','Alle Projekte','quiet','data-view="projects"')+'</div>'+projectTable(recent)+'</div><div class="grid two"><div class="card"><h3>Aktuelle Preisgrundlage</h3><p>'+esc(activePrice().name)+'</p><span class="badge">'+activePrice().articles+' Artikelpositionen · '+activePrice().services+' Leistungen</span><p class="muted" style="margin-top:14px">Neue Preisstände gelten für neue Kalkulationen. Gespeicherte Projekte behalten ihre Grundlage.</p>'+btn('navigate','Preisdatei verwalten','','data-view="upload"')+'</div><div class="card"><h3>Datensicherung</h3><div class="info">Cloud-Daten sind zugriffsgeschützt. Administratoren können zusätzlich eine vollständige Datensicherung herunterladen.</div>'+btn('backup-export','Datensicherung herunterladen')+'</div></div>';}
function projectInvoice(p){if(p.status==='Entwurf'&&!p.protected){return D.calculation(setProjectBasis(clone(p),activeParameters(),activePrice())).metrics?.invoice;}return p.snapshot?.metrics?.invoice;}
