function projectsPage(){return heading('Meine Projekte','Gespeicherte Projekte öffnen, kopieren und auf ihrer ursprünglichen Preisgrundlage weiterführen.',btn('new-project','+ Neue Kalkulation','primary'))+'<div class="card"><div class="subheading"><h2>Projektübersicht</h2><input class="search" data-search="projects" placeholder="Projekt, Kunde oder Nummer suchen" value="'+esc(search)+'" aria-label="Projekte suchen"></div>'+projectTable(state.projects.filter(p=>[p.title,p.customer,p.number].join(' ').toLowerCase().includes(search.toLowerCase())))+'</div>';}
