 if(step===4){h+='<div class="card"><h2>Einrüstung</h2><div class="selection-grid">'+['C','D','F'].map(c=>'<div>'+checkbox(P,c+'72',KP_SOURCE.sheets[P][c+'71']?.v||'Einrüstung')+'<div style="padding:6px 12px">'+input(P,c+'73','Betrag / '+(KP_SOURCE.sheets[P][c+'71']?.v||'Einrüstung')+' (€)','number')+'</div></div>').join('')+'</div></div><div class="card"><div class="subheading"><div><h2>Nachträge / zusätzliche Leistungen</h2><p class="muted">Zusätzliche, frei kalkulierte Netto-Verkaufspositionen außerhalb der Preislisten. Rabatt und Skonto können je Position ausgeschlossen werden.</p></div>'+btn('add-supplement','+ Position hinzufügen','',projectReadOnly()?'disabled':'')+'</div>'+supplementEditor()+'</div><div class="card"><h2>Rabatt & Skonto</h2><div class="selection-grid">'+(project.pricingModel===13?'<p>Kalkulatorischer Provisionsanteil und maximaler Skonto werden automatisch berücksichtigt.</p>':checkbox(P,'E9','Prozentualen TGA-Kundenrabatt berücksichtigen')+checkbox(P,'F9','Pauschalen TGA-Kundenrabatt berücksichtigen')+checkbox(P,'G9','Skonto berücksichtigen'))+'</div><div class="info">Rabatt und Skonto werden in der Angebotsbildung entsprechend der Excel-Formeln aufgerechnet. Die hinterlegten Sätze gehören zur Preisgrundlage dieses Projekts.</div></div>';}
