function catalogServiceEditor(){const catalog=Array.isArray(project.pdsCatalog)?project.pdsCatalog:[],rows=project.catalogServices??[];if(!catalog.length)return '<div class="warning">Bitte zuerst einen PDS-Preisstand importieren. Danach stehen hier alle PDS-Leistungen zur Auswahl.</div>';if(!rows.length)return '<div class="empty"><p>Noch keine zusätzliche Katalogleistung ausgewählt.</p></div>';return '<div class="table-wrap"><table><thead><tr><th>Leistung aus PDS</th><th class="num">Menge</th><th class="num">Arbeitszeit</th><th>Monteur</th><th>Geselle</th><th>Azubi</th><th>Meister</th><th></th></tr></thead><tbody>'+rows.map((x,i)=>'<tr><td><select data-catalog="'+i+'" data-kind="serviceId" '+(projectReadOnly()?'disabled':'')+'><option value="">Bitte auswählen</option>'+catalog.map(s=>'<option value="'+esc(s.id)+'" '+(x.serviceId===s.id?'selected':'')+'>'+esc((s.name?s.name+' · ':'')+(s.text||'Ohne Bezeichnung'))+' · '+fmt(Number(s.total||0),'€')+'</option>').join('')+'</select></td><td><input data-catalog="'+i+'" data-kind="quantity" type="number" step="any" min="0" value="'+esc(x.quantity??1)+'" '+(projectReadOnly()?'disabled':'')+'></td><td><input data-catalog="'+i+'" data-kind="hours" type="number" step="any" min="0" value="'+esc(x.hours??0)+'" '+(projectReadOnly()?'disabled':'')+'><small>h je Menge und ausgewählter Mitarbeitergruppe</small></td>'+[['monteur','Monteur'],['geselle','Geselle'],['azubi','Azubi'],['meister','Meister']].map(([k,l])=>'<td><label class="check"><input data-catalog="'+i+'" data-role="'+k+'" type="checkbox" '+(x.roles?.[k]?'checked':'')+' '+(projectReadOnly()?'disabled':'')+'><span>'+l+'</span></label></td>').join('')+'<td>'+btn('remove-catalog-service','Entfernen','quiet','data-index="'+i+'" '+(projectReadOnly()?'disabled':''))+'</td></tr>').join('')+'</tbody></table><div style="margin-top:14px">'+btn('add-catalog-service','+ Weitere Leistung','',projectReadOnly()?'disabled':'')+'</div></div>';}
function materialTable(lines,actual){if(!lines.length)return '<p class="muted">Für die aktuelle Auswahl sind noch keine Artikelstücklisten aktiviert.</p>';let lastService=null,body='';for(const l of lines){if(l.service!==lastService){lastService=l.service;body+='<tr class="material-service"><td colspan="'+(actual?7:4)+'"><span class="badge green">Leistung</span><strong>'+esc(l.service||'Zugeordnete Leistung')+'</strong></td></tr>';}let a=project.actual?.material?.[l.id]||{},difference=a.price!=null&&a.quantity!=null?a.quantity*a.price-l.quantity*l.price:null;body+='<tr class="material-article"><td><span class="material-indent"><span class="badge">Artikel</span><strong>'+esc(l.name||l.text)+'</strong><small>'+esc(l.text)+'</small></span></td><td class="num">'+fmt(l.quantity)+' '+esc(l.unit)+'</td><td class="num">'+fmt(l.price,'€')+'</td><td class="num">'+fmt(l.quantity*l.price,'€')+'</td>'+(actual?'<td><input type="number" step="any" min="0" data-material="'+l.id+'" data-kind="quantity" value="'+esc(a.quantity??'')+'" placeholder="'+esc(l.quantity)+'" aria-label="Ist-Menge '+esc(l.text)+'" '+(project.actual.status==='Abgeschlossen'?'disabled':'')+'></td><td><input type="number" step="0.01" min="0" data-material="'+l.id+'" data-kind="price" value="'+inputNum(a.price)+'" placeholder="'+inputNum(l.price)+'" aria-label="Ist-Einkaufspreis '+esc(l.text)+'" '+(project.actual.status==='Abgeschlossen'?'disabled':'')+'><input type="text" data-material="'+l.id+'" data-kind="reason" value="'+esc(a.reason??'')+'" placeholder="Grund bei Nullwert" aria-label="Nullwert-Begründung '+esc(l.text)+'" '+(project.actual.status==='Abgeschlossen'?'disabled':'')+'><small>EK-Abweichung je Einheit: '+fmt(a.price==null?null:a.price-l.price,'€')+'</small></td><td class="num">'+fmt(difference,'€')+'</td>':'')+'</tr>';}return '<div class="table-wrap"><table class="material-table"><thead><tr><th>Artikel / Leistung</th><th class="num">Soll-Menge</th><th class="num">Soll-EK</th><th class="num">Soll gesamt</th>'+(actual?'<th>Ist-Menge</th><th>Ist-EK</th><th class="num">Gesamtabweichung</th>':'')+'</tr></thead><tbody>'+body+'</tbody></table></div>';}
function issueBox(issues){return issues.length?'<div class="warning"><strong>Bitte prüfen</strong><ul>'+issues.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':'<div class="success">Alle erforderlichen Angaben für die Vorkalkulation sind vorhanden.</div>'}
function supplementEditor(){if(!Array.isArray(project.supplements)){project.supplements=D.supplementItems(project);project.inputs[P]??={};['C','D','E','F','G','H','I','J'].forEach(c=>project.inputs[P][c+'77']=0);}const rows=project.supplements||[];if(!rows.length)return '<div class="empty"><p>Noch keine zusätzliche Leistung erfasst.</p></div>';return '<div class="table-wrap"><table><thead><tr><th>Beschreibung</th><th class="num">Betrag netto</th><th class="num">Kalk. Kosten</th><th>Rabatt</th><th>Skonto</th><th></th></tr></thead><tbody>'+rows.map((x,i)=>'<tr><td><input data-supplement="'+i+'" data-kind="description" type="text" value="'+esc(x.description||'')+'" '+(projectReadOnly()?'disabled':'')+' placeholder="z. B. 10 Steckdosen inkl. Leitungsverlegung"></td><td><input data-supplement="'+i+'" data-kind="amount" type="number" step="0.01" min="0" value="'+esc(x.amount??'')+'" '+(projectReadOnly()?'disabled':'')+'></td><td><input data-supplement="'+i+'" data-kind="plannedCost" type="number" step="0.01" min="0" value="'+esc(x.plannedCost??'')+'" '+(projectReadOnly()?'disabled':'')+'></td><td><label class="check"><input data-supplement="'+i+'" data-kind="excludeDiscount" type="checkbox" '+(x.excludeDiscount?'checked':'')+' '+(projectReadOnly()?'disabled':'')+'><span>von Rabatt ausgeschlossen</span></label></td><td><label class="check"><input data-supplement="'+i+'" data-kind="excludeSkonto" type="checkbox" '+(x.excludeSkonto?'checked':'')+' '+(projectReadOnly()?'disabled':'')+'><span>von Skonto ausgeschlossen</span></label></td><td>'+btn('remove-supplement','Entfernen','quiet','data-index="'+i+'" '+(projectReadOnly()?'disabled':''))+'</td></tr>').join('')+'</tbody></table></div>';}
function resultPage(calc){let m=calc.metrics;let h='<div class="card"><h2>Kalkulationsergebnis</h2>'+issueBox(calc.issues);if(m){const overheadRate=calc.engine.safe(B,'I10'),profitRate=calc.engine.safe(B,'H10');h+='<div class="result-waterfall">'+[['Material-EK',m.material],['Gemeinkosten auf Material-EK ('+pct(overheadRate)+')',m.overhead],['Personalkosten Montage / weitere Zeit',m.montagePersonnel],['Personalkosten Fahrtzeit',m.travelPersonnel],['Mitarbeiterbonus',m.bonus],['Fahrzeugkosten',m.vehicle],['Reise / Hotel / Fähre / Spesen',m.travelOther],['Kalkulierte Kosten Zusatzleistungen',m.supplementPlannedCost],['Selbstkosten',m.selfCost,'subtotal'],['Gewinnzuschlag ('+pct(profitRate)+')',calc.engine.safe(C,'D183')],['Entfernungspauschale',calc.engine.safe(C,'D184')],['Inselzuschlag',calc.engine.safe(C,'D185')],['Bar-VK Basis',m.baseRevenue,'subtotal'],['Nachträge / zusätzliche Leistungen',m.supplementRevenue],['Kalkulierter Ergebnisbeitrag Zusatzleistungen',m.supplementContribution],[(project.pricingModel===13?'Kalkulatorischer Provisionsanteil':'Rabatt-Aufrechnung gesamt')+' ('+pct(m.plannedDiscount)+')',m.plannedDiscountAmount],['Pauschaler Kundenrabatt',calc.engine.safe(C,'D189')],['Skonto-Aufrechnung gesamt ('+pct(m.plannedSkonto)+')',m.plannedSkontoAmount],['Angebots-VK netto',m.invoice,'total']].map(([l,x,c])=>'<div class="'+(c||'')+'"><span>'+l+'</span><strong>'+fmt(x,'€')+'</strong></div>').join('')+'</div>';}
 h+='<details><summary>Alle Berechnungsdetails anzeigen</summary>'+detailsTable(calc.rows)+'</details><p class="note-box">Preisdatei: '+esc(project.priceName)+' · Parameterstand: '+esc(project.parameterVersion)+' · Ersteller: '+esc(project.creator)+'</p></div><div class="card"><h2>Preis-Gewinn-Optimizer</h2><p class="muted">Original-Optimizer aus Excel mit vier unabhängigen Vergleichsständen. Die erweiterte Nachkalkulation steht separat zur Verfügung.</p>'+optimizerPage(calc)+'</div><div class="card"><h2>Projektverlauf</h2><p class="muted">'+(project.history?.length?project.history.map(x=>esc(date(x.date))+' · '+esc(x.action)).join('<br>'):'Noch keine gespeicherten Änderungen.')+'</p>'+btn('toggle-protection',project.protected?'Speicherschutz aufheben':'Speicherschutz aktivieren','',project.status==='Abgeschlossen'?'disabled':'')+'</div>';return h;}
function detailsTable(rows){return '<div class="table-wrap"><table class="details-table"><thead><tr><th>Berechnung</th><th class="num">Wert</th><th>Hinweis</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.label)+'</td><td class="num">'+fmt(r.value,r.unit||'')+'</td><td><small>'+esc(r.note)+'</small></td></tr>').join('')+'</tbody></table></div>';}
function optimizerDefault(cell,calc){const m=calc.metrics||{};const map={E3:m.invoice,E4:project.pricingModel===13?0:m.plannedDiscount,E5:m.plannedSkonto,E6:(m.montageRoleHours?.[0]||0)+(m.travelByRole?.[0]||0),E8:(m.montageRoleHours?.[1]||0)+(m.travelByRole?.[1]||0),E10:(m.montageRoleHours?.[2]||0)+(m.travelByRole?.[2]||0),E12:(m.montageRoleHours?.[3]||0)+(m.travelByRole?.[3]||0),E14:(m.montageRoleHours?.[4]||0)+(m.travelByRole?.[4]||0),E16:getInput(P,'C9')?'Peter Jensen':'TGA'};return map[cell]??'';}
function optimizerPage(calc){let values=project.optimizer.values,origin=getInput(P,'C9')===true?'Peter Jensen':getInput(P,'D9')===true?'TGA':optimizerDefault('E16',calc),effective={};['E3','E4','E5','E6','E8','E10','E12','E14'].forEach(c=>effective[c]=values[c]??optimizerDefault(c,calc));effective.E16=origin;project.optimizer.values.E16=origin;let opt=D.optimizerResults(project,effective),e=opt.engine,optValues=opt.values;let fields=[['E3','Rechnungswert netto (€)'],['E4','Gewährter Rabatt (%)'],['E5','Gewährter Skonto (%)'],['E6','Ist-h Monteur inkl. Fahrt'],['E8','Ist-h Azubi inkl. Fahrt'],['E10','Ist-h Geselle inkl. Fahrt'],['E12','Ist-h Meister inkl. Fahrt'],['E14','Ist-h Projekt-/Bauleiter inkl. Fahrt']];
 let h='<div class="form-grid">'+fields.map(([c,l])=>'<label>'+l+'<input type="number" step="any" min="0" data-optimizer="'+c+'" value="'+inputNum(values[c]??optimizerDefault(c,calc))+'"></label>').join('')+'<label>Kundenherkunft im Optimizer<select data-optimizer="E16" disabled><option '+(origin==='TGA'?'selected':'')+'>TGA</option><option '+(origin==='Peter Jensen'?'selected':'')+'>Peter Jensen</option></select><small>Wird automatisch aus Projekt & Kunde übernommen.</small></label></div><div class="divider"></div><div class="table-wrap"><table><thead><tr><th>Ergebnis</th><th class="num">Aktuell</th>'+[0,1,2,3].map(i=>'<th class="num">Stand '+(i+1)+'</th>').join('')+'</tr></thead><tbody>';
 for(let r=204;r<=212;r++){h+='<tr><td>'+esc(D.visibleText(e.safe(O,'C'+r)))+'</td><td class="num">'+fmt(optValues['E'+r],'€')+'</td>'+project.optimizer.slots.map(x=>'<td class="num">'+fmt(x?.values?.['E'+r],'€')+'</td>').join('')+'</tr>';}h+='<tr><td>Vergleichsstand</td><td></td>'+project.optimizer.slots.map((x,i)=>'<td class="num">'+btn('optimizer-save','Speichern','','data-slot="'+i+'"')+' '+btn('optimizer-clear','Löschen','','data-slot="'+i+'" '+(!x?'disabled':''))+'</td>').join('')+'</tr></tbody></table></div><div class="info">Der Optimizer berücksichtigt bei Nachträgen die projektspezifischen Ausschlüsse von Rabatt und Skonto und ersetzt ansonsten wie bisher die Mitarbeiterkosten. Er berücksichtigt keine umfassenden Ist-Material- oder Ist-Reisekosten. Die neue Nachkalkulation darunter erfasst diese Kosten vollständig.</div>';return h;}
const actualLabels={commission:'Tatsächliche Provisionsabrechnung / Gutschrift (€)',invoice:'Tatsächlicher Rechnungsbetrag netto (€)',discount:'Tatsächlich gewährter Rabatt (%)',skonto:'Tatsächlich gezogener Skonto (%)',kilometers:'Tatsächliche Fahrzeugkilometer',travelOther:'Reise / Hotel / Fähre / Spesen tatsächlich (€)',foreign:'Zusätzliche Fremdleistungen (€)',other:'Weitere sonstige Projektkosten (€)',materialResidual:'Übrige Excel-Materialpositionen / Pauschalen tatsächlich (€)',bonus:'Mitarbeiterbonus tatsächlich (€)',credit:'Pauschale Nachlässe / Gutschriften tatsächlich (€)'};D.roles.forEach((r,i)=>{actualLabels['montage'+i]=r+' · Montage / weitere Projektzeit (h)';actualLabels['travel'+i]=r+' · Fahrtzeit (h)'});
