document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)action(el).catch(ex=>showError(ex.message));});
document.addEventListener('input',e=>{const x=e.target;if(!logged)return;if(x.dataset.search){search=x.value;const start=x.selectionStart;render();const n=$('[data-search]');n.focus();n.setSelectionRange(start,start);return}if(x.dataset.project&&project&&!projectReadOnly()&&x.tagName!=='SELECT'){project[x.dataset.project]=x.type==='checkbox'?x.checked:x.type==='number'?Number(x.value):x.value;mark();}if(x.dataset.catalog!=null&&project&&!projectReadOnly()&&!x.dataset.role){const row=project.catalogServices?.[+x.dataset.catalog];if(row&&x.dataset.kind!=='serviceId'){row[x.dataset.kind]=x.value===''?null:Number(x.value);mark();}}if(x.dataset.supplement!=null&&project&&!projectReadOnly()){const i=+x.dataset.supplement;project.supplements??=[];const row=project.supplements[i];if(row){row[x.dataset.kind]=['amount','plannedCost'].includes(x.dataset.kind)?(x.value===''?null:Number(x.value)):x.value;mark();}}if(x.dataset.sheet&&project&&!projectReadOnly()){const sheet=x.dataset.sheet,cell=x.dataset.cell;project.inputs[sheet]??={};project.inputs[sheet][cell]=x.type==='checkbox'?x.checked:x.type==='number'?(x.value===''?null:Number(x.value)):x.value;mark();}if(x.dataset.paramSheet&&isAdmin()){paramDraft[x.dataset.paramSheet]??={};paramDraft[x.dataset.paramSheet][x.dataset.paramCell]=x.type==='checkbox'?x.checked:x.value===''?null:Number(x.value);dirty=true;}if(x.dataset.actual&&project.actual.status!=='Abgeschlossen'){project.actual.values[x.dataset.actual]=x.value===''?null:Number(x.value);mark()}if(x.dataset.zero&&project.actual.status!=='Abgeschlossen'){project.actual.zeroReasons[x.dataset.zero]=x.value;mark()}if(x.dataset.material&&project.actual.status!=='Abgeschlossen'){project.actual.material[x.dataset.material]??={};project.actual.material[x.dataset.material][x.dataset.kind]=x.dataset.kind==='reason'?x.value:x.value===''?null:Number(x.value);mark()}if(x.dataset.actualMeta&&project.actual.status!=='Abgeschlossen'){project.actual[x.dataset.actualMeta]=x.type==='checkbox'?x.checked:x.value;mark()}if(x.dataset.optimizer&&!projectReadOnly()){project.optimizer.values[x.dataset.optimizer]=x.dataset.optimizer==='E16'?x.value:x.value===''?null:Number(x.value);dirty=true;}});
document.addEventListener('change',e=>{const x=e.target;if(x.dataset.catalog!=null&&project&&!projectReadOnly()){const row=project.catalogServices?.[+x.dataset.catalog];if(row){if(x.dataset.role){row.roles??={};row.roles[x.dataset.role]=x.checked;}else if(x.dataset.kind==='serviceId')row.serviceId=x.value;mark();render();return;}}if(x.dataset.supplement!=null&&project&&!projectReadOnly()&&x.type==='checkbox'){const row=project.supplements?.[+x.dataset.supplement];if(row){row[x.dataset.kind]=x.checked;mark();}}if(x.dataset.roof&&project&&!projectReadOnly()){let r=x.dataset.roof;project.inputs[P]??={};['D','E','F','G','H'].forEach(c=>project.inputs[P][c+r]=x.value===c);mark()}if(x.dataset.sheet&&x.type==='checkbox'&&project&&!projectReadOnly()){let cell=x.dataset.cell;if(['C72','D72','F72'].includes(cell)){project.inputs[P].P19=['C72','D72','F72'].some(c=>c===cell?x.checked:project.inputs[P][c]===true);}if(cell==='C9'&&x.checked)project.inputs[P].D9=false;if(cell==='D9'&&x.checked)project.inputs[P].C9=false;if(['C41','E41','G41'].includes(cell)&&x.checked)['C41','E41','G41'].filter(c=>c!==cell).forEach(c=>project.inputs[P][c]=false);for(let r of [86,89,92,95])if(['J'+r,'K'+r].includes(cell)&&x.checked)project.inputs[P][(cell[0]==='J'?'K':'J')+r]=false;render()}if(x.dataset.optimizer){render()}if(x.dataset.project&&x.tagName==='SELECT'){if(x.dataset.project==='status'){const oldStatus=project.status,newStatus=x.value;if(oldStatus==='Abgeschlossen'){x.value=oldStatus;return}if(newStatus==='Entwurf'&&oldStatus!=='Entwurf'){if(!confirm('Das Projekt verwendet anschließend wieder die aktuellen Stammdaten und Preise. Dadurch kann sich das Kalkulationsergebnis ändern. Fortfahren?')){x.value=oldStatus;return}project.status='Entwurf';syncDraftBasis(project);}else{project.status=newStatus;if(newStatus==='In Bearbeitung'){project.history??=[];project.history.push({date:now(),user:USER,action:'Preis- und Parameterstand durch Status „In Bearbeitung“ eingefroren'});}}dirty=true;render();return;}project[x.dataset.project]=x.value;dirty=true;}if(x.dataset.actualMeta&&x.tagName==='SELECT'){project.actual[x.dataset.actualMeta]=x.value;dirty=true;}});
$('#csv-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;await busy('PDS-Export wird geprüft …',async()=>{if(!/\.csv$/i.test(f.name))throw Error('Bitte einen PDS-CSV-Export auswählen.');if(f.size>10*1024*1024)throw Error('Der PDS-Export darf höchstens 10 MB groß sein.');const bytes=await f.arrayBuffer();let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{text=new TextDecoder('windows-1252').decode(bytes)}const parsed=D.importCSV(text,KP_SOURCE.sheets);pendingCSV={name:f.name,text,parsed};$('#modal-content').innerHTML='<h2>PDS-Export geprüft</h2><p><strong>'+esc(f.name)+'</strong><br>'+parsed.articles+' Artikelpositionen · '+parsed.uniqueArticles+' unterschiedliche Artikel / Beschreibungen · '+parsed.services+' Leistungen</p>'+ (parsed.errors.length?'<div class="warning"><strong>'+parsed.errors.length+' Fehler – Datei wird nicht übernommen</strong><ul>'+parsed.errors.slice(0,40).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':'<div class="success">PDS-Struktur ist gültig; alle Leistungen werden in den KalkPro-Katalog übernommen. Der bisherige Preisstand wird als Historie erhalten.</div>')+(parsed.warnings?.length?'<div class="info"><strong>'+parsed.warnings.length+' Hinweis(e)</strong><ul>'+parsed.warnings.slice(0,40).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':'')+'<div class="actions">'+btn('csv-confirm','PDS-EK-Preisstand übernehmen','primary',parsed.errors.length?'disabled':'')+btn('close-modal','Abbrechen')+'</div>';$('#modal').showModal();});});
function validateBackup(next){if(next.matrixHistory!=null&&!Array.isArray(next.matrixHistory))throw Error('Ungültige Matrixhistorie.');for(const m of [next.matrixCurrent,...(next.matrixHistory||[])].filter(Boolean))if(!m.id||!m.basis||!Array.isArray(m.pv)||!Array.isArray(m.ac)||!m.assumptions||!Number.isFinite(m.average)||!m.pv.every(x=>Array.isArray(x.rows)&&x.rows.every(r=>Array.isArray(r.cells)&&r.cells.length===20&&r.cells.every(c=>Number.isFinite(c.total)&&c.metrics))))throw Error('Unvollständiger Preismatrixstand in der Sicherung.');if(next.format!=='KalkPro-TGA'||next.schema!==1||next.sourceHash!==KP_SOURCE.sourceSha256||!Array.isArray(next.projects)||!Array.isArray(next.priceVersions)||!Array.isArray(next.parameterVersions))throw Error('Die Datei ist keine kompatible KalkPro-TGA-V0.1-Sicherung.');if(!next.priceVersions.some(x=>x.id===next.activePrice)||!next.parameterVersions.some(x=>x.id===next.activeParameters))throw Error('Aktive Preis- oder Parameterstände fehlen.');let ids=new Set();for(const p of next.projects){if(!p.id||ids.has(p.id)||!p.inputs?.[P]||!Array.isArray(p.history)||!p.optimizer?.values||!Array.isArray(p.optimizer.slots)||p.optimizer.slots.length!==4)throw Error('Ein Projekt in der Sicherung ist unvollständig.');ids.add(p.id);D.calculation(p)}if(!Number.isInteger(next.lastNumber)||next.lastNumber<0)throw Error('Projektzähler fehlt.');for(const m of [next.matrixCurrent,...(next.matrixHistory||[])].filter(Boolean))KPMatrix.hydrateDetails(m);return next;}
$('#backup-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;await busy('Datensicherung wird geprüft …',async()=>{if(f.size>100*1024*1024)throw Error('Die Sicherung ist größer als 100 MB.');const txt=await f.text();const next=JSON.parse(txt,(k,v)=>{if(['__proto__','constructor','prototype'].includes(k))throw Error('Unzulässiger Sicherungsinhalt.');return v});action.backup=validateBackup(next);confirmDialog('Datensicherung wiederherstellen?',next.projects.length+' Projekte sowie Preis- und Parameterhistorie werden geladen. Der aktive Cloud-Datenbestand wird nach vollständigem Import ersetzt. Vorher bei Bedarf eine Sicherung herunterladen.','backup-confirm');});});
